#include <bits/stdc++.h>
using namespace std;

struct Tree {
    int n;
    vector<vector<int>> adj;
    vector<int> dist, par, order;

    explicit Tree(int n_) : n(n_), adj(n_), dist(n_), par(n_) {}

    void add(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // BFS que retorna o no mais distante; preenche dist e par
    int bfs(int s) {
        fill(dist.begin(), dist.end(), -1);
        fill(par.begin(), par.end(), -1);
        order.clear();
        order.reserve(n);
        dist[s] = 0;
        order.push_back(s);
        for (size_t i = 0; i < order.size(); ++i) {
            int u = order[i];
            for (int v : adj[u]) {
                if (dist[v] < 0) {
                    dist[v] = dist[u] + 1;
                    par[v] = u;
                    order.push_back(v);
                }
            }
        }
        return order.back(); // ultimo processado = mais distante
    }

    // Centro da arvore (no com minima excentricidade)
    int center() {
        int a = bfs(0);   // extremo de um diametro
        int b = bfs(a);   // outro extremo; dist[b] = diametro
        int d = dist[b];
        // reconstruir caminho de b ate a
        vector<int> path;
        path.reserve(d + 1);
        for (int cur = b; cur != -1; cur = par[cur]) path.push_back(cur);
        // centros ficam nas posicoes centrais do caminho do diametro
        int c1 = path[d / 2];
        int c2 = path[d - d / 2];
        return min(c1, c2);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    Tree A(N), B(M);

    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        A.add(u - 1, v - 1);
    }
    for (int i = 0; i < M - 1; ++i) {
        int u, v;
        cin >> u >> v;
        B.add(u - 1, v - 1);
    }

    // O diâmetro mínimo ao unir duas arvores com uma aresta é
    // max(d1, d2, ceil(d1/2) + 1 + ceil(d2/2)),
    // alcançado ligando os centros das duas arvores.
    cout << A.center() + 1 << ' ' << B.center() + 1 << '\n';
    return 0;
}
